namespace sv_24059a597e43455daff6cb47fe4c9c45.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit (per user).
/// Survives enhanced navigations; isolated between users.
/// </summary>
public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// All interactive components subscribe to this to re-render on changes.
    /// </summary>
    public event Action? OnChanged;

    private void NotifyChanged() => OnChanged?.Invoke();
}

@* Interactive island placed inside the static MainLayout *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="badge"
      style="background-color: @ThemeService.AccentColor; cursor: pointer;"
      title="Current theme"
      @onclick="CycleTheme">
    @Icon @ThemeService.Theme
</span>

@code {
    private string Icon => ThemeService.Theme switch
    {
        ThemeMode.Light  => "☀️",
        ThemeMode.Dark   => "🌙",
        _                => "💻"
    };

    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleChanged;
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    private void CycleTheme()
    {
        ThemeService.Theme = ThemeService.Theme switch
        {
            ThemeMode.Light  => ThemeMode.Dark,
            ThemeMode.Dark   => ThemeMode.System,
            _                => ThemeMode.Light
        };
    }

    public void Dispose() => ThemeService.OnChanged -= HandleChanged;
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px; border-left: 4px solid @ThemeService.AccentColor;">
    <h4>Theme</h4>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <button class="btn @(ThemeService.Theme == mode ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => ThemeService.Theme = mode">
                @mode
            </button>
        }
    </div>

    <h4>Accent Color</h4>
    <div class="d-flex align-items-center gap-3 mb-3">
        <input type="color"
               class="form-control form-control-color"
               value="@ThemeService.AccentColor"
               @onchange="e => ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd"" />
        <span class="badge" style="background-color: @ThemeService.AccentColor;">
            @ThemeService.AccentColor
        </span>
    </div>

    <p class="text-muted small mb-0">
        Changes apply instantly across all components, including the header indicator.
    </p>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleChanged;
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => ThemeService.OnChanged -= HandleChanged;
}

